function validate(input) {
  const [{ Weather = [] }] = input;
  const ids = new Set(), days = new Set();
  for (const [id, day, temperature] of Weather) {
    if (id === null || day === null || temperature === null) return 'Every reading needs an id, a recordDate and a temperature.';
    if (ids.has(id)) return `id ${id} appears twice in Weather.`;
    ids.add(id);
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(day);
    const d = m && new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
    if (!d || d.getUTCMonth() !== +m[2] - 1 || d.getUTCDate() !== +m[3]) return `recordDate ${day} is not a valid YYYY-MM-DD date.`;
    if (days.has(day)) return `recordDate ${day} appears twice in Weather.`;
    days.add(day);
  }
  return null;
}

